using SkiaSharp;
using System.Text.Json;
var output=args[0];Directory.CreateDirectory(output);var values=new Dictionary<string,object?>();var cases=new List<object>();using var pixels=File.Create(Path.Combine(output,"pixels.bin"));int checks=0;void Check(bool b){checks++;if(!b)throw new Exception("Final paint check "+checks);}
float[] Floats(SKColorF c)=>[c.Red,c.Green,c.Blue,c.Alpha];
using(var p=new SKPaint()){values["defaults"]=new{color=Floats(p.ColorF),dither=p.IsDither,blender=p.Blender is not null,mode=p.BlendMode.ToString()};p.Blender=SKBlender.CreateBlendMode(SKBlendMode.Multiply);values["blend-mode"]=new{mode=p.BlendMode.ToString(),has=p.Blender is not null};p.BlendMode=SKBlendMode.Src;values["blend-after-mode"]=p.Blender is not null;p.Blender=null;values["blend-null"]=p.BlendMode.ToString();p.ColorF=new(-.2f,1.4f,.45678f,2);values["extended-color"]=Floats(p.ColorF);values["extended-byte"]=p.Color.ToString();p.Reset();values["reset"]=new{color=Floats(p.ColorF),dither=p.IsDither,blender=p.Blender is not null};}
int index=0;
foreach(var tagged in new[]{false,true})foreach(var linear in new[]{false,true})foreach(float alpha in new[]{.137f,.5f,1f})
{
 using var cs=tagged?SKColorSpace.CreateSrgb():null;using var source=linear?SKColorSpace.CreateSrgbLinear():null;using var b=new SKBitmap(new SKImageInfo(48,32,SKColorType.Rgba8888,SKAlphaType.Premul,cs));using var c=new SKCanvas(b);c.Clear(new(30,50,70,180));using var p=new SKPaint();p.SetColor(new(.133333f,.577777f,.89999f,alpha),source!);values[$"color-{index}"]=Floats(p.ColorF);c.DrawRect(4,3,38,25,p);cases.Add(new{kind="float-color",scene=index++,transform=0,offset=pixels.Position,length=b.ByteCount});pixels.Write(b.GetPixelSpan());
}
foreach(var mode in new[]{SKBlendMode.SrcOver,SKBlendMode.Multiply,SKBlendMode.DstIn})foreach(int draw in new[]{0,1,2})
{
 using var b=new SKBitmap(48,32);using var c=new SKCanvas(b);c.Clear(new(45,110,170,190));using var p=new SKPaint{Color=new(230,65,35,150),Blender=SKBlender.CreateBlendMode(mode),IsAntialias=true};if(draw==0)c.DrawRect(4.2f,3.3f,37,25,p);if(draw==1){using var g=SKShader.CreateLinearGradient(new(0,0),new(48,32),[SKColors.Red,SKColors.Blue],SKShaderTileMode.Clamp);p.Shader=g;c.DrawCircle(24,16,13,p);}if(draw==2){using var source=new SKBitmap(8,6);source.Erase(new(220,30,60,130));c.DrawBitmap(source,new SKRect(4.2f,3.3f,41.2f,28.3f),p);}cases.Add(new{kind="mode-blender",scene=index++,transform=0,offset=pixels.Position,length=b.ByteCount});pixels.Write(b.GetPixelSpan());
}
foreach(bool enforce in new[]{false,true})foreach(int draw in new[]{0,1,2})
{
 using var b=new SKBitmap(48,32);using var c=new SKCanvas(b);c.Clear(new(45,110,170,190));using var blender=SKBlender.CreateArithmetic(.4f,.3f,.2f,.15f,enforce);using var p=new SKPaint{Color=new(230,65,35,150),Blender=blender,IsAntialias=true};blender.Dispose();using var clone=p.Clone();p.Reset();if(draw==0)c.DrawRect(4.2f,3.3f,37,25,clone);if(draw==1){using var g=SKShader.CreateLinearGradient(new(0,0),new(48,32),[SKColors.Red,SKColors.Blue],SKShaderTileMode.Clamp);clone.Shader=g;c.DrawCircle(24,16,13,clone);}if(draw==2){using var source=new SKBitmap(8,6);source.Erase(new(220,30,60,130));c.DrawBitmap(source,new SKRect(4.2f,3.3f,41.2f,28.3f),clone);}cases.Add(new{kind="arithmetic-blender",scene=index++,transform=0,offset=pixels.Position,length=b.ByteCount});pixels.Write(b.GetPixelSpan());
}
foreach(bool dither in new[]{false,true}){using var b=new SKBitmap(48,32);using var c=new SKCanvas(b);using var g=SKShader.CreateLinearGradient(new(0,0),new(48,0),[new SKColorF(.03f,.05f,.07f),new SKColorF(.08f,.11f,.13f)],null!,SKShaderTileMode.Clamp);using var p=new SKPaint{Shader=g,IsDither=dither};using var clone=p.Clone();Check(clone.IsDither==dither);c.DrawRect(0,0,48,32,clone);cases.Add(new{kind="dither",scene=index++,transform=0,offset=pixels.Position,length=b.ByteCount});pixels.Write(b.GetPixelSpan());}
File.WriteAllText(Path.Combine(output,"values.json"),JsonSerializer.Serialize(values));File.WriteAllText(Path.Combine(output,"cases.json"),JsonSerializer.Serialize(cases));File.WriteAllText(Path.Combine(output,"local.json"),JsonSerializer.Serialize(new{checks}));Console.WriteLine($"PASS {cases.Count} final paint draws");
